public class BoundedQueueWorkerPool {
    // Trade-off: We chose a synchronous blocking queue with a bounded capacity
    // over an unbounded LinkedBlockingQueue. 
    // Cost: Potential request rejection under peak load (ThreadPoolRejectedExecutionException).
    // Benefit: Prevents OutOfMemoryError (OOM) by capping memory allocation for queued tasks.

    private final ThreadPoolExecutor executor = new ThreadPoolExecutor(
        4, 16,
        60L, TimeUnit.SECONDS,
        new ArrayBlockingQueue<>(1000),
        r -> new Thread(r, "worker-pool-" + r.hashCode()),
        new ThreadPoolExecutor.CallerRunsPolicy() // Mitigation: Push back to caller thread
    );

    public void submitTask(Runnable task) {
        executor.execute(task);
    }
}
